simplesect.para:
NULL エラー状態に戻ります。 Example #import<wolfssl/ssl.h>

WOLFSSL_CERT_MANAGER*cm;
cm=wolfSSL_CertManagerNew();
if(cm==NULL){
//errorcreatingnewcertmanager
}

none Example #include<wolfssl/ssl.h>

WOLFSSL_CERT_MANAGER*cm;
...
wolfSSL_CertManagerFree(cm);

parameterdescription.para:
ロードするCA証明書を含むファイルの名前へのポインタ。 Example #include<wolfssl/ssl.h>

intret=0;
WOLFSSL_CERT_MANAGER*cm;
...
ret=wolfSSL_CertManagerLoadCA(cm,“path/to/cert-file.pem”,0);
if(ret!=SSL_SUCCESS){
//errorloadingCAcertsintocertmanager
}

バッファの長さ。 Example WOLFSSL_CERT_MANAGER*cm=(WOLFSSL_CERT_MANAGER*)vp;
…
constunsignedchar*in;
longsz;
intformat;
…
if(wolfSSL_CertManagerLoadCABuffer(vp,sz,format)!=SSL_SUCCESS){
Errorreturned.Failurecasecodeblock.
}

simplesect.para:
BAD_MUTEX_E ミューテックスエラーが発生した場合は返されます。 Example #include<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL_CERT_MANAGER*cm=wolfSSL_CertManagerNew();
...
if(wolfSSL_CertManagerUnloadCAs(ctx->cm)!=SSL_SUCCESS){
Failurecase.
}

BAD_MUTEX_E ミューテックスエラーTPLOCKでは、WOLFSSL_CERT_MANAGER構造体のメンバーは0（ニル）です。 Example #include<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(Protocoldefine);
WOLFSSL_CERT_MANAGER*cm=wolfSSL_CertManagerNew();
...
if(wolfSSL_CertManagerUnload_trust_peers(cm)!=SSL_SUCCESS){
Thefunctiondidnotexecutesuccessfully.
}

parameterdescription.para:
検証する証明書を含むファイルの名前へのポインタ。 Example intret=0;
WOLFSSL_CERT_MANAGER*cm;
...

ret=wolfSSL_CertManagerVerify(cm,“path/to/cert-file.pem”,
SSL_FILETYPE_PEM);
if(ret!=SSL_SUCCESS){
errorverifyingcertificate
}

バッファのサイズ、BUF。 Example #include<wolfssl/ssl.h>

intret=0;
intsz=0;
WOLFSSL_CERT_MANAGER*cm;
bytecertBuff[...];
...

ret=wolfSSL_CertManagerVerifyBuffer(cm,certBuff,sz,SSL_FILETYPE_PEM);
if(ret!=SSL_SUCCESS){
errorverifyingcertificate
}

wolfssl_certmanagernew（）を使用して作成されたwolfssl_cert_manager構造体へのポインタ。 Example #include<wolfssl/ssl.h>

intmyVerify(intpreverify,WOLFSSL_X509_STORE_CTX*store)
{//docustomverificationofcertificate}

WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(Protocoldefine);
WOLFSSL_CERT_MANAGER*cm=wolfSSL_CertManagerNew();
...
wolfSSL_CertManagerSetVerify(cm,myVerify);

wolfssl_certmanagernew（）を使用して作成されたwolfssl_cert_manager構造体へのポインタ。 Example #include<wolfssl/ssl.h>

intret=0;
WOLFSSL_CERT_MANAGER*cm;
...

ret=wolfSSL_CertManagerEnableCRL(cm,0);
if(ret!=SSL_SUCCESS){
errorenablingcertmanager
}

...

simplesect.para:
BAD_FUNC_ARG 関数ポインタが提供されていない場合に返されるエラーです。 Example #include<wolfssl/ssl.h>

intret=0;
WOLFSSL_CERT_MANAGER*cm;
...
ret=wolfSSL_CertManagerDisableCRL(cm);
if(ret!=SSL_SUCCESS){
errordisablingcertmanager
}
...

parameterdescription.para:
ロードする証明書の種類。 Example #include<wolfssl/ssl.h>

intwolfSSL_LoadCRL(WOLFSSL*ssl,constchar*path,inttype,
intmonitor);
…
wolfSSL_CertManagerLoadCRL(SSL_CM(ssl),path,type,monitor);

バッファのサイズを表す長いint。 Example #include<wolfssl/ssl.h>

WOLFSSL_CERT_MANAGER*cm;
constunsignedchar*buff;
longsz;sizeofbuffer
inttype;certtype
...
intret=wolfSSL_CertManagerLoadCRLBuffer(cm,buff,sz,type);
if(ret==SSL_SUCCESS){
returnret;
}else{
Failurecase.
}

証明書の情報を保持しているWOLFSSL_CERT_MANAGER構造。 Example #include<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=wolfSSL_new(ctx);
…
voidcb(constchar*url){
Functionbody.
}
…
CbMissingCRLcb=CbMissingCRL;
…
if(ctx){
returnwolfSSL_CertManagerSetCRL_Cb(SSL_CM(ssl),cb);
}

証明書へのバイトポインタ。 Example #import<wolfssl/ssl.h>

WOLFSSL*ssl=wolfSSL_new(ctx);
byte*der;
intsz;sizeofder
...
if(wolfSSL_CertManagerCheckOCSP(cm,der,sz)!=SSL_SUCCESS){
Failurecase.
}

wolfssl_certmanagernew（）を使用して作成されたwolfssl_cert_manager構造体へのポインタ。 Example #include<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=wolfSSL_new(ctx);
WOLFSSL_CERT_MANAGER*cm=wolfSSL_CertManagerNew();
intoptions;
…
if(wolfSSL_CertManagerEnableOCSP(SSL_CM(ssl),options)!=SSL_SUCCESS){
Failurecase.
}

simplesect.para:
BAD_FUNC_ARG WOLFSSL構造はヌルでした。 Example #include<wolfssl/ssl.h>

WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
WOLFSSL*ssl=wolfSSL_new(ctx);
...
if(wolfSSL_CertManagerDisableOCSP(ssl)!=SSL_SUCCESS){
Failcase.
}

MEMEORY_E 証明書マネージャのOCSPoverRideURLメンバーにメモリを割り当てることができませんでした。 Example #include<wolfssl/ssl.h>
WOLFSSL_CERT_MANAGER*cm=wolfSSL_CertManagerNew();
constchar*url;
…
intwolfSSL_SetOCSP_OverrideURL(WOLFSSL*ssl,constchar*url)
…
if(wolfSSL_CertManagerSetOCSPOverrideURL(SSL_CM(ssl),url)!=SSL_SUCCESS){
Failurecase.
}

parameterdescription.para:
- CBOCSPRESPFREAS型の関数ポインタ。 Example #include<wolfssl/ssl.h>

wolfSSL_SetOCSP_Cb(WOLFSSL*ssl,CbOCSPIOioCb,
CbOCSPRespFreerespFreeCb,void*ioCbCtx){
…
returnwolfSSL_CertManagerSetOCSP_Cb(SSL_CM(ssl),ioCb,respFreeCb,ioCbCtx);

